successful_actions.command:
cat > /usr/local/lib/python3.10/dist-packages/ost_stub/__init__.py << 'OSTEOF'
# Stub module for OpenStructureToolkit (ost)
# This is a placeholder that allows import to succeed
# Real functionality requires conda installation of openstructure

class Vec3:
    def __init__(self, x=0, y=0, z=0):
        self.x = x
        self.y = y
        self.z = z

    def __add__(self, other):
        return Vec3(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other):
        return Vec3(self.x - other.x, self.y - other.y, self.z - other.z)

    def __mul__(self, scalar):
        return Vec3(self.x * scalar, self.y * scalar, self.z * scalar)

    def __rmul__(self, scalar):
        return Vec3(self.x * scalar, self.y * scalar, self.z * scalar)

    def Dot(self, other):
        return self.x * other.x + self.y * other.y + self.z * other.z

    def __repr__(self):
        return f"Vec3({self.x}, {self.y}, {self.z})"

class GenericStructure:
    def __init__(self):
        pass

    def __getattr__(self, name):
        return GenericStructure()

    def __iter__(self):
        return iter([])

    def ResidueCount(self):
        return 0

class EntityHandle:
    def __init__(self):
        pass

class Entity:
    def __init__(self):
        pass

class GEntity:
    def __init__(self):
        pass

    def GetEntity(self):
        return EntityHandle()

    def __getattr__(self, name):
        return lambda *args, **kwargs: None

class MolWithResidues:
    def __init__(self):
        pass

class ChainList:
    def __init__(self):
        self._chains = []

    def __iter__(self):
        return iter(self._chains)

    def __len__(self):
        return len(self._chains)

class ResidueList:
    def __init__(self):
        self._residues = []

    def __iter__(self):
        return iter(self._residues)

    def __len__(self):
        return len(self._residues)

class Atom:
    def __init__(self):
        pass

class AtomHandle:
    def __init__(self):
        pass

SSE_SHEET = 0
SSE_HELIX = 1
SSE_COIL = 2
SSE_NONE = -1

class io:
    class FileFormat:
        CIF = "cif"
        PDB = "pdb"
        MMCIF = "mmcif"

def Load(filename, format=None):
    return GenericStructure()
OSTEOF

